::: {.cell-output-display}

```{=html}
<div class="airfoil-filters">
<div class="form-group shiny-input-container">
<label class="control-label" id="filter_metric-label" for="filter_metric">Métrica:</label>
<div>
<select id="filter_metric" class="shiny-input-select"><option value="cl_alpha" selected>Cl x Alfa</option>
<option value="cd_alpha">Cd x Alfa</option>
<option value="clcd_alpha">(Cd/Cl) Alfa</option></select>
<script type="application/json" data-for="filter_metric" data-nonempty="">{"plugins":["selectize-plugin-a11y"]}</script>
</div>
</div>
<div class="form-group shiny-input-container">
<label class="control-label" id="filter_axis_x-label" for="filter_axis_x">Eixo X:</label>
<div>
<select id="filter_axis_x" class="shiny-input-select"><option value="alpha" selected>Alfa (Ângulo de Ataque)</option></select>
<script type="application/json" data-for="filter_axis_x" data-nonempty="">{"plugins":["selectize-plugin-a11y"]}</script>
</div>
</div>
<div id="filter_airfoil" class="form-group shiny-input-checkboxgroup shiny-input-container" role="group" aria-labelledby="filter_airfoil-label">
<label class="control-label" id="filter_airfoil-label" for="filter_airfoil">Visualizar Perfis:</label>
<div class="shiny-options-group">
<div class="checkbox">
<label>
<input type="checkbox" name="filter_airfoil" value="airfoil_wing"/>
<span>Asa</span>
</label>
</div>
